CREATE OR REPLACE FUNCTION public.set_staff_role(target uuid, new_role public.app_role, grant_role boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN PERFORM pg_advisory_xact_lock(824711); IF NOT public.has_permission('roles.manage') THEN RAISE EXCEPTION 'Access denied' USING ERRCODE='42501'; END IF; IF new_role NOT IN ('owner','admin','moderator') THEN RAISE EXCEPTION 'Invalid staff role'; END IF; IF grant_role THEN IF NOT EXISTS(SELECT 1 FROM auth.users WHERE id=target AND email_confirmed_at IS NOT NULL) THEN RAISE EXCEPTION 'Choose a verified account'; END IF; INSERT INTO public.user_roles(user_id,role) VALUES(target,new_role) ON CONFLICT(user_id,role) DO NOTHING; ELSE DELETE FROM public.user_roles WHERE user_id=target AND role=new_role; END IF; END $$;
CREATE OR REPLACE FUNCTION public.staff_directory() RETURNS TABLE(user_id uuid,email text,role public.app_role) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.has_permission('roles.manage') THEN RAISE EXCEPTION 'Access denied' USING ERRCODE='42501'; END IF; RETURN QUERY SELECT r.user_id,u.email::text,r.role FROM public.user_roles r JOIN auth.users u ON u.id=r.user_id WHERE r.role IN ('owner','admin','moderator'); END $$;
CREATE OR REPLACE FUNCTION public.verified_staff_target(address text) RETURNS uuid LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE target uuid; BEGIN IF NOT public.has_permission('roles.manage') THEN RAISE EXCEPTION 'Access denied' USING ERRCODE='42501'; END IF; SELECT id INTO target FROM auth.users WHERE lower(email)=lower(trim(address)) AND email_confirmed_at IS NOT NULL; IF target IS NULL THEN RAISE EXCEPTION 'Verified account not found'; END IF; RETURN target; END $$;